    @EventHandler( payloadType=CreateAgencyEvent.class )
    public void handle( CreateAgencyEvent event) {
	    LOGGER.info("handling CreateAgencyEvent - " + event );
	    Agency entity = new Agency();
            entity.setAgencyId( event.getAgencyId() );
            entity.setName( event.getName() );
            entity.setLegalName( event.getLegalName() );
            entity.setHeadquartersCountry( event.getHeadquartersCountry() );
            entity.setWebsite( event.getWebsite() );
	    
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    create(entity);
        
        // ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllAgency( entity );
    }

