    /**
     * Method to retrieve the Agency via an AgencyPrimaryKey.
     * @param 	id Long
     * @return 	Agency
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Agency handle( FindAgencyQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getAgencyId() );
    }
    
    /**
     * Method to retrieve a collection of all Agencys
     *
     * @param	query	FindAllAgencyQuery 
     * @return 	List<Agency> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Agency> handle( FindAllAgencyQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindAgency,
 * but only if the id matches
 *
 * @param		entity	Agency
 */
	protected void emitFindAgency( Agency entity ) {
		LOGGER.info("handling emitFindAgency" );
		
	    queryUpdateEmitter.emit(FindAgencyQuery.class,
	                            query -> query.getFilter().getAgencyId().equals(entity.getAgencyId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllAgency
	 * 
	 * @param		entity	Agency
	 */
	protected void emitFindAllAgency( Agency entity ) {
		LOGGER.info("handling emitFindAllAgency" );
		
	    queryUpdateEmitter.emit(FindAllAgencyQuery.class,
	                            query -> true,
	                            entity);
	}

